//! Live name lists retain their real Document root and authoritative attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><input id=main name=child></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://owned-name.test/",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){assert_eq!(p.console_eval(d,f,s).errors,0,"{}",p.report());}
#[test]
fn owned_name_list_inert_html_xml_generic_exact_namespace_tree_and_owner_changes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var ns='http://www.w3.org/1999/xhtml';for(var owner of [document.implementation.createHTMLDocument('inert'),document.implementation.createDocument(null,'Root'),new Document()]){var root=owner.body||owner.documentElement;if(!root){root=owner.createElementNS(ns,'section');owner.appendChild(root);}var a=owner.createElementNS(ns,'span'),b=owner.createElementNS(ns,'span'),literal=owner.createElementNS(ns,'span'),foreign=owner.createElementNS('urn:other','Other'),wrong=owner.createElementNS(ns,'span');a.setAttribute('name','A\ud800');b.setAttribute('name','next');literal.setAttribute('name','A�');foreign.setAttribute('name','A\ud800');wrong.setAttributeNS('urn:attr','name','A\ud800');for(var leaf of [a,b,literal,foreign,wrong])root.appendChild(leaf);var list=owner.getElementsByName('A\ud800');if(!(list instanceof NodeList)||list.length!==1||list[0]!==a||list.item(1)!==null||owner.getElementsByName('A�')[0]!==literal||owner.getElementsByName('a\ud800').length!==0)throw 'actual names and namespaces';b.setAttribute('name','A\ud800');root.insertBefore(b,a);if(list.length!==2||list[0]!==b||list[1]!==a)throw 'live tree order';root.removeChild(b);if(list.length!==1||list[0]!==a)throw 'disconnected excluded';var target=new Document(),targetRoot=target.createElementNS(ns,'section');target.appendChild(targetRoot);target.adoptNode(a);if(list.length!==0||target.getElementsByName('A\ud800').length!==0)throw 'owner is not ancestry';targetRoot.appendChild(a);if(target.getElementsByName('A\ud800')[0]!==a)throw 'actual adopted root';var template=owner.createElementNS(ns,'template'),inside=template.content.ownerDocument.createElement('span');inside.setAttribute('name','A\ud800');template.content.appendChild(inside);root.appendChild(template);if(list.length!==0||template.content.ownerDocument.getElementsByName('A\ud800').length!==0)throw 'associated template document is not contents';var empty=owner.createElementNS(ns,'span');empty.setAttribute('name','');root.appendChild(empty);if(owner.getElementsByName('').length!==1||owner.getElementsByName('')[0]!==empty)throw 'empty is not absent';}
"#);}
#[test]
fn owned_name_list_inert_conversion_effects_are_once_live_and_abrupt(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('inert'),a=owner.createElement('span');owner.body.appendChild(a);var calls=0,list=owner.getElementsByName({toString:function(){calls++;a.setAttribute('name','X\udfff');return 'X\udfff';}});if(calls!==1||list.length!==1||list[0]!==a)throw 'once converted before live view';var marker={};try{owner.getElementsByName({toString:function(){calls++;a.setAttribute('name','effect');throw marker;}});throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(calls!==2||list.length!==0||owner.getElementsByName('effect')[0]!==a)throw 'abrupt author effect';Object.defineProperty(Element.prototype,'name',{configurable:true,get:function(){throw 'author name';}});Object.defineProperty(Node.prototype,'childNodes',{configurable:true,get:function(){throw 'author children';}});if(owner.getElementsByName('effect')[0]!==a)throw 'native facts';
"#);}

#[test]
fn owned_name_list_filter_admission_and_combined_scratch_refusal_recover_without_identity_leaks(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=new Document(),leaf=owner.createElementNS('http://www.w3.org/1999/xhtml','span');leaf.setAttribute('name','A\\ud800');owner.appendChild(leaf);");
 let Value::Host(root)=p.runtime.execute("owner",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("owner")};let Value::Host(leaf)=p.runtime.execute("leaf",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("leaf")};p.state.rebuild(&d).unwrap();
 let value=Value::StringUnits(vec![65,0xd800]);let before=(p.state.retained,p.state.node_lists.len(),p.state.node_lists.capacity(),p.state.dom_commits);let(limit,strings)=(p.state.retained_limit,p.state.limits.host.string_bytes);
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.retained_limit=before.0,_=>p.state.limits.host.string_bytes=3};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.create_document_name_list(root,&value).is_err());assert_eq!((p.state.retained,p.state.node_lists.len(),p.state.node_lists.capacity(),p.state.dom_commits),before);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;}
 p.begin_job();let Value::Host(handle)=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.create_document_name_list(root,&value).unwrap()else{panic!("list")};let after=p.state.retained;let queries::NodeList::RootedName{root:saved,name}=&p.state.node_lists[before.1]else{panic!("filter")};assert_eq!(*saved,root);assert_eq!(name.raw_units(),Some(&[65,0xd800][..]));assert_eq!(after-before.0,(p.state.node_lists.capacity()-before.2)*size_of::<queries::NodeList>()+name.capacity());
 for mode in 0..3{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,_=>p.state.retained_limit=after+19};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.node_list_get(handle,"length").is_err());assert_eq!((p.state.retained,p.state.node_lists.len(),p.state.dom_commits),(after,before.1+1,before.3));p.state.retained_limit=limit;}
 p.begin_job();p.state.retained_limit=after+20;let mut b=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert_eq!(b.node_list_get(handle,"length").unwrap().to_number(),1.0);assert!(matches!(b.node_list_get(handle,"0").unwrap(),Value::Host(node) if node==leaf));assert_eq!(b.state.retained,after);
}
